92	function startServer(t, dataDir) {
93	  const proc = spawn(
94	    serverBin,
95	    ['serve', '--host', '127.0.0.1', '--port', '0', '--data-dir', dataDir],
96	    { stdio: ['ignore', 'pipe', 'inherit'] },
97	  );
98	  t.after(() => { proc.kill('SIGKILL'); });
99	  return new Promise((resolve, reject) => {
100	    let buf = '';
101	    const timer = setTimeout(() => reject(new Error('等待服务监听地址超时')), 15000);
102	    proc.stdout.on('data', (chunk) => {
103	      buf += chunk.toString();
104	      const m = buf.match(/listening on (http:\/\/\S+)/);
105	      if (m) {
106	        clearTimeout(timer);
107	        resolve(m[1]);
108	      }
109	    });
110	    proc.on('exit', (code) => {
111	      clearTimeout(timer);
112	      reject(new Error(`服务在输出监听地址前退出，退出码 ${code}`));
113	    });
114	  });
115	}
