122	// 种子房间，用于比对创建前后的列表内容与次序。
123	async function setupPage(t) {
124	  const dataDir = await mkdtemp(path.join(tmpdir(), 'score-arena-uidata-'));
125	  t.after(() => rm(dataDir, { recursive: true, force: true }));
126	  await seedRooms(dataDir, SEED_ALPHA, SEED_BETA);
127	  const baseURL = await startServer(t, dataDir);
128	  const page = await browser.newPage();
129	  t.after(() => page.close());
130	  await page.goto(baseURL, { waitUntil: 'load' });
131	  await waitForRowCount(page, 2);
132	  return { page, baseURL };
133	}
