155	    trs.map((tr) => {
156	      const tds = [...tr.querySelectorAll('td')];
157	      return {
158	        cells: tds.map((td) => td.textContent),
159	        timeTitle: tds[6] ? tds[6].getAttribute('title') : null,
160	        badge: tds[5] && tds[5].querySelector('.badge')
161	          ? tds[5].querySelector('.badge').textContent
162	          : null,
163	      };
164	    }),
165	  );
166	}
