209	function nextCreated(page) {
210	  return new Promise((resolve, reject) => {
211	    page.on('response', (resp) => {
212	      if (resp.request().method() === 'POST' && resp.url().endsWith('/api/rooms')) {
213	        resp.json().then(resolve, reject);
214	      }
215	    });
216	  });
217	}
