239	    await page.waitForFunction(
240	      () => !document.getElementById('capacity').disabled,
241	      { timeout: 5000 },
242	    );
243	    await page.select('#capacity', String(c.capacity));
244	  }
245	  if (c.rawTurn !== '') await page.type('#turnSeconds', c.rawTurn);
