454	// 看到时间错误后“只修改时间这一项”再提交：修正为合法值后按修正后的秒数
455	// 创建，先前被拒绝的值不进入记录，原先填好的名称、规则、人数继续沿用；
456	// 成功后按现有行为复位表单并刷新列表，错误提示被成功结果替换。
457	// =============================================================================
458	
459	// 范围错误（9）→ 仅把时间改为上端点 600，五子棋固定 2 人沿用。
460	test('范围错误后只把时间改为 600：按 600 创建，被拒的 9 不进入记录，其余配置沿用', { timeout: 60000 }, async (t) => {
461	  const { page, baseURL } = await setupPage(t);
462	  const postBodies = trackRoomPosts(page);
463	
464	  const initialRows = await readRows(page);
465	  assertSeedRows(initialRows);
466	
467	  const c = {
468	    name: '修正时间五子棋', game: 'gomoku', capacity: 2, rawTurn: '9',
469	  };
470	  await fillForm(page, c);
471	  const blockedMsg = await expectBlocked(page, baseURL, postBodies, initialRows, MSG_TURN_RANGE);
472	
473	  // 拦截后名称/规则/人数/时间均保留。
474	  assert.deepEqual(await readFormState(page), {
475	    name: c.name, game: 'gomoku', capacity: '2',
476	    capacityDisabled: false, turnSeconds: '9', submitDisabled: false,
477	  });
478	
479	  // 用户只修改时间这一项（名称、规则、人数完全不触碰）为合法的 600。
480	  await replaceTurn(page, '600');
481	  const createdPromise = nextCreated(page);
482	  await page.click('#submit');
483	
484	  await waitForMessageKind(page, 'ok');
485	  const created = await createdPromise;
486	
487	  // 拦截时不发请求，修正后只发出一次请求，且请求体沿用原名称/规则/人数、
488	  // 携带修正后的秒数 600（先前被拒的 9 不得进入请求或记录）。
489	  assert.equal(postBodies.length, 1, '拦截时不发请求，修正后应只发出一次创建请求');
490	  assert.deepEqual(JSON.parse(postBodies[0]), {
491	    name: c.name, game: 'gomoku', capacity: 2, turnSeconds: 600,
492	  }, '请求体必须沿用原名称/规则/人数并使用修正后的秒数');
493	  assert.equal(created.turnSeconds, 600, '创建结果必须按修正后的 600 秒保存');
494	  assert.equal(created.game, 'gomoku');
495	  assert.equal(created.capacity, 2);
496	
497	  // 错误提示被本次成功结果替换：展示成功编号，旧的范围错误文案消失。
498	  const msg = await readMessage(page);
499	  assert.ok(msg.className.includes('ok'), '修正成功后应显示成功提示而非错误提示');
500	  assert.ok(msg.text.startsWith(SUCCESS_PREFIX));
501	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id);
502	  assert.ok(!msg.text.includes(blockedMsg), '修正成功后旧的时间错误提示应被替换');
503	
504	  // 列表追加新房间并显示 600 秒；原有房间内容与次序不变。
505	  await waitForRowCount(page, 3);
506	  const rows = await readRows(page);
507	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
508	  assert.deepEqual(rows[2].cells.slice(0, 5), [
509	    created.id, c.name, '五子棋', '2 人', '600 秒',
510	  ], '新增行应沿用原名称/规则/人数并显示修正后的秒数');
511	
512	  // 服务端只多出本次一条记录，秒数为 600；先前被拒的 9 不存在于任何记录。
513	  const serverRooms = await readServerRooms(baseURL);
514	  assert.equal(serverRooms.length, 3);
515	  assert.equal(serverRooms[2].id, created.id);
516	  assert.equal(serverRooms[2].turnSeconds, 600, '列表记录应保存修正后的秒数');
517	  assert.ok(
518	    !serverRooms.some((r) => r.turnSeconds === 9),
519	    '先前被拒绝的 9 秒不得进入任何房间记录',
520	  );
521	
522	  // 成功后按现有行为清空表单、恢复未选择规则时的人数状态。
523	  assert.deepEqual(await readFormState(page), RESET_FORM, '成功后表单应复位');
524	});
525	
526	// 小数错误（30.5）→ 仅把时间改为 0，飞行棋 3 人与原名称沿用，结果为不限时。
527	test('小数错误后只把时间改为 0：按不限时创建，30.5 不进入记录，飞行棋 3 人沿用', { timeout: 60000 }, async (t) => {
528	  const { page, baseURL } = await setupPage(t);
529	  const postBodies = trackRoomPosts(page);
530	
531	  const initialRows = await readRows(page);
532	  assertSeedRows(initialRows);
533	
534	  const c = {
535	    name: '修正小数飞行棋', game: 'ludo', capacity: 3, rawTurn: '30.5',
536	  };
537	  await fillForm(page, c);
538	  const blockedMsg = await expectBlocked(page, baseURL, postBodies, initialRows, MSG_TURN_INTEGER);
539	
540	  // 拦截后已填内容保留（含飞行棋规则与 3 人）。
541	  assert.deepEqual(await readFormState(page), {
542	    name: c.name, game: 'ludo', capacity: '3',
543	    capacityDisabled: false, turnSeconds: '30.5', submitDisabled: false,
544	  });
545	
546	  // 只改时间为 0（不限时），其余不触碰。
547	  await replaceTurn(page, '0');
548	  const createdPromise = nextCreated(page);
549	  await page.click('#submit');
550	
551	  await waitForMessageKind(page, 'ok');
552	  const created = await createdPromise;
553	
554	  assert.equal(postBodies.length, 1, '拦截时不发请求，修正后应只发出一次创建请求');
555	  assert.deepEqual(JSON.parse(postBodies[0]), {
556	    name: c.name, game: 'ludo', capacity: 3, turnSeconds: 0,
557	  }, '请求体必须沿用飞行棋 3 人与原名称，并提交修正后的 0');
558	  assert.equal(created.turnSeconds, 0, '创建结果必须按修正后的 0（不限时）保存');
559	  assert.equal(created.capacity, 3, '原先选好的飞行棋 3 人应继续用于本次创建');
560	
561	  const msg = await readMessage(page);
562	  assert.ok(msg.className.includes('ok'));
563	  assert.equal(msg.text.slice(SUCCESS_PREFIX.length), created.id);
564	  assert.ok(!msg.text.includes(blockedMsg), '修正成功后旧的小数错误提示应被替换');
565	
566	  await waitForRowCount(page, 3);
567	  const rows = await readRows(page);
568	  assert.deepEqual(rows.slice(0, 2), initialRows, '原有房间的内容或次序被改变');
569	  assert.deepEqual(rows[2].cells.slice(0, 5), [
570	    created.id, c.name, '飞行棋', '3 人', '不限时',
571	  ], '修正为 0 后新行应显示“不限时”，规则与人数沿用');
572	
573	  const serverRooms = await readServerRooms(baseURL);
574	  assert.equal(serverRooms.length, 3);
575	  const saved = serverRooms[2];
576	  assert.equal(saved.id, created.id);
577	  assert.equal(saved.turnSeconds, 0, '列表记录应保存修正后的 0');
578	  assert.equal(saved.capacity, 3);
579	
580	  // 成功后按现有行为复位表单（人数重新禁用，等待下一次选择规则）。
581	  assert.deepEqual(await readFormState(page), RESET_FORM, '成功后表单应复位');
582	});
583

