function checkForm(raw) {
  var nameLen = Array.from(trimName(raw.name)).length;
  if (nameLen === 0) return { error: '房间名称不能为空。' };
  if (!raw.game) return { error: '请选择游戏规则。' };
  if (raw.capacity === '') return { error: '请选择人数上限。' };
  if (raw.turnSeconds === '') return { error: '请填写每步时间限制（0 表示不限时）。' };
  if (!/^-?\d+$/.test(raw.turnSeconds)) return { error: '时间限制必须是整数秒，不能含小数。' };

  // 通过必填与整数格式检查后再转换：空值不会变成 0，不合法文字不会变成秒数。
  var capacity = parseInt(raw.capacity, 10);
  var turnSeconds = Number(raw.turnSeconds);

  if (nameLen > 40) return { error: '房间名称去掉首尾空白后不能超过 40 个字符。' };
  if (raw.game !== 'gomoku' && raw.game !== 'ludo') return { error: '请选择游戏规则。' };
  if (raw.game === 'gomoku' && capacity !== 2) return { error: '五子棋的人数上限固定为 2 人。' };
  if (raw.game === 'ludo' && !(capacity >= 2 && capacity <= 4)) {
    return { error: '飞行棋的人数上限必须为 2 至 4 人。' };
  }
  if (turnSeconds !== 0 && !(turnSeconds >= 10 && turnSeconds <= 600)) {
    return { error: '每步时间限制只能填 0（不限时）或 10 至 600 之间的整数秒。' };
  }

  return {
    payload: {
      name: raw.name,
      game: raw.game,
      capacity: capacity,
      turnSeconds: turnSeconds
    }
  };
}

